import ctypes as C,re,xml.etree.ElementTree as E
c=C.CDLL('libcairo.so.2');P=C.c_void_p;D=C.c_double;I=C.c_int

def fn(n,args,ret=None):
 f=getattr(c,'cairo_'+n);f.argtypes=args;f.restype=ret;return f
create=fn('image_surface_create',[I,I,I],P);context=fn('create',[P],P)
save=fn('save',[P]);restore=fn('restore',[P]);translate=fn('translate',[P,D,D]);scale=fn('scale',[P,D,D]);new=fn('new_path',[P]);move=fn('move_to',[P,D,D]);line=fn('line_to',[P,D,D]);curve=fn('curve_to',[P,D,D,D,D,D,D]);close=fn('close_path',[P]);source=fn('set_source_rgb',[P,D,D,D]);paint=fn('paint',[P]);fill=fn('fill_preserve',[P]);stroke=fn('stroke',[P]);width=fn('set_line_width',[P,D]);cap=fn('set_line_cap',[P,I]);write=fn('surface_write_to_png',[P,C.c_char_p],I)

def color(ctx,h): source(ctx,*[int(h[i:i+2],16)/255 for i in [1,3,5]])
def draw(ctx,e,inherit='#000000'):
 save(ctx)
 for typ,args in re.findall(r'(translate|scale)\\((["'^)]+)'"\\)',e.get('transform','')):
  a=[float(v) for v in re.split('[ ,]+',args)]
  if typ=='translate':translate(ctx,a[0],a[1] if len(a)>1 else 0)
  else:scale(ctx,a[0],a[1] if len(a)>1 else a[0])
 f=e.get('fill',inherit)
 if e.tag.endswith('path'):
  new(ctx);ts=re.findall('[MLCVZ]|[-+]?(?:\\d*\\.\\d+|\\d+)',e.get('d',''));j=0;x=y=0
  while j<len(ts):
   cmd=ts[j];j+=1
   if cmd=='Z':close(ctx);continue
   count={'M':2,'L':2,'C':6,'V':1}[cmd];v=list(map(float,ts[j:j+count]));j+=count
   if cmd=='M':move(ctx,*v);x,y=v
   elif cmd=='L':line(ctx,*v);x,y=v
   elif cmd=='C':curve(ctx,*v);x,y=v[-2:]
   elif cmd=='V':y=v[0];line(ctx,x,y)
  if f"'!='"'none':color(ctx,f);fill(ctx)
  if e.get('stroke'):
   color(ctx,e.get('stroke'));width(ctx,float(e.get('stroke-width','1')));cap(ctx,1);stroke(ctx)
 for ch in e:draw(ctx,ch,f)
 restore(ctx)
s=create(0,900,620);ctx=context(s);color(ctx,'#F6F2E8');paint(ctx)
logo=E.parse('logo.svg').getroot();save(ctx);translate(ctx,90,18);draw(ctx,logo);restore(ctx)
color(ctx,'#FFFFFF');new(ctx);move(ctx,0,430);line(ctx,900,430);line(ctx,900,620);line(ctx,0,620);close(ctx);fill(ctx)
mark=E.parse('mark.svg').getroot()
for x,sz in [(275,96),(430,48),(540,32),(630,16)]:
 save(ctx);translate(ctx,x,470);scale(ctx,sz/64,sz/64);draw(ctx,mark);restore(ctx)
write(s,b'/tmp/fernway-preview.png')
PY
